@extends('layouts.app') @section('content')<section class="hero"><div class="eyebrow">Laravel · CRUD</div><h1>Keep work moving without losing the details.</h1><p class="lead">Search, filter, create, update and safely remove tasks.</p></section><form class="card" method="get"><div class="form-grid"><div class="field"><label>Search</label><input name="search" value="{{ request('search') }}" placeholder="Title or description"></div><div class="field"><label>Status</label><select name="status"><option value="">All</option>@foreach(['todo','in_progress','done'] as $v)<option value="{{ $v }}" @selected(request('status')===$v)>{{ str_replace('_',' ',ucfirst($v)) }}</option>@endforeach</select></div></div><button class="btn" type="submit">Apply filters</button> <a class="btn secondary" href="{{ route('tasks.index') }}">Reset</a></form><section class="card"><h2>Task queue</h2><div class="table-wrap"><table><thead><tr><th>Task</th><th>Status</th><th>Priority</th><th>Actions</th></tr></thead><tbody>@forelse($tasks as $task)<tr><td><a href="{{ route('tasks.show',$task) }}"><strong>{{ $task->title }}</strong></a></td><td>{{ str_replace('_',' ',ucfirst($task->status)) }}</td><td>{{ ucfirst($task->priority) }}</td><td><a class="btn secondary" href="{{ route('tasks.edit',$task) }}">Edit</a> <form style="display:inline" method="post" action="{{ route('tasks.destroy',$task) }}" onsubmit="return confirm('Delete this task?')">@csrf @method('DELETE')<button class="btn danger" type="submit">Delete</button></form></td></tr>@empty<tr><td colspan="4" class="empty">No matching tasks. Create one or reset your filters.</td></tr>@endforelse</tbody></table></div>{{ $tasks->links() }}</section>@endsection
